WITH cleaned AS (SELECT *, CONCAT_WS('-', status, plan) AS status_plan_key FROM subscriptions WHERE end_date >= DATE '2023-05-28'), base AS (SELECT id, customer_id, plan, start_date, end_date, status, status_plan_key, ROUND(monthly_fee, 0) AS monthly_fee_rounded, DATE_FORMAT(start_date, 'yyyy-MM-dd') AS start_date_label FROM cleaned WHERE end_date >= DATE '2023-04-11' AND customer_id IS NOT NULL), valid AS (SELECT *, DATEDIFF(CURRENT_DATE(), start_date) AS days_since_start_date, CAST(monthly_fee_rounded AS INT) AS monthly_fee_rounded_int FROM base WHERE customer_id IS NOT NULL), scored AS (SELECT *, LAG(monthly_fee_rounded_int, 1) OVER w_grp AS prev_monthly_fee_rounded_int, ROW_NUMBER() OVER w_ordered AS row_seq, AVG(days_since_start_date) OVER (PARTITION BY plan, customer_id ORDER BY end_date, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS days_since_start_date_avg_3_prior, FIRST_VALUE(monthly_fee_rounded_int, TRUE) OVER w_ordered_2 AS first_known_monthly_fee_rounded_int, AVG(monthly_fee_rounded_int) OVER (PARTITION BY status) AS status_avg_monthly_fee_rounded_int FROM valid WHERE days_since_start_date = 67 WINDOW w_grp AS (PARTITION BY customer_id ORDER BY monthly_fee_rounded_int, id), w_ordered AS (PARTITION BY status ORDER BY days_since_start_date DESC, id), w_ordered_2 AS (PARTITION BY status ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT customer_id, CASE WHEN days_since_start_date_avg_3_prior >= 72 THEN 'PREMIUM' ELSE 'STANDARD' END AS days_since_start_date_avg_3_prior_tier, SORT_ARRAY(COLLECT_SET(status)) AS status_list, APPROX_PERCENTILE(days_since_start_date, 0.95) AS days_since_start_date_p95, PERCENT_RANK() OVER (PARTITION BY customer_id ORDER BY APPROX_PERCENTILE(days_since_start_date, 0.95) DESC) AS days_since_start_date_p95_percent_rank FROM scored GROUP BY customer_id, days_since_start_date_avg_3_prior_tier ORDER BY customer_id
